_choice_scp_cipher() {
    command -v ssh >/dev/null 2>&1 || return 0
    ssh -Q cipher 2>/dev/null
}

_choice_scp_host() {
    if [[ -n "$ARGC_COMPLETIONS_ROOT" ]]; then
        _argc_util_cache 60 _choice_scp_host_uncached "scp_host:${argc_F:-$HOME/.ssh/config}:$HOME/.ssh/known_hosts"
