}

_choice_scp_host_uncached() {
    {
        _helper_scp_host_config
        _helper_scp_host_known
        _helper_scp_host_etc
    } | gawk '!seen[$0]++'
}

_choice_scp_path() {
    # An scp:// URI is left as free text; splitting on ':' would treat the scheme as a host.
    if [[ "$ARGC_CWORD" == *://* ]]; then
        return 0
    fi
    _argc_util_mode_kv :
    if [[ -z "$argc__kv_prefix" ]]; then
