_helper_scp_host_config() {
    local config="${argc_F:-$HOME/.ssh/config}"
    [[ -f "$config" ]] || return 0
    gawk '
        /^[[:space:]]*#/ { next }
        {
            line = $0
            sub(/^[[:space:]]+/, "", line)
            if (tolower(line) !~ /^host[[:space:]]/) next
            sub(/^[Hh][Oo][Ss][Tt][[:space:]]+/, "", line)
            sub(/[[:space:]]*#.*$/, "", line)
            n = split(line, hosts, /[[:space:]]+/)
            for (i = 1; i <= n; i++) {
                h = hosts[i]
                if (h == "" || h ~ /[*?!]/) continue
                print h
            }
        }
    ' "$config"
}

_helper_scp_host_etc() {
    [[ -f /etc/hosts ]] || return 0
    gawk '
        /^[[:space:]]*#/ { next }
        NF >= 2 { for (i = 2; i <= NF; i++) print $i }
    ' /etc/hosts
}

_helper_scp_host_known() {
    local file="$HOME/.ssh/known_hosts"
    [[ -f "$file" ]] || return 0
    gawk '
        /^[[:space:]]*#/ { next }
        NF == 0 { next }
        {
            n = split($1, hosts, ",")
            for (i = 1; i <= n; i++) {
                h = hosts[i]
                if (h ~ /^\|/) continue
                sub(/^\[/, "", h)
                sub(/\]:[0-9]+$/, "", h)
                sub(/:.*/, "", h)
                if (h != "" && h !~ /[*?]/) print h
            }
        }
    ' "$file"
}
